import pytest


def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs chosen deterministically
    from seed, without using randomness.

    The same xs and seed always give the same element. Any integer seed,
    including negative or very large values, is valid, and the result is
    always a member of xs. Raises ValueError if xs is empty.
    """
    if not xs:
        raise ValueError("xs must be non-empty")
    return xs[seed % len(xs)]


def test_pick_returns_member() -> None:
    xs = [10, 20, 30, 40]
    for seed in range(-20, 20):
        assert pick(xs, seed) in xs


def test_pick_deterministic() -> None:
    xs = [5, 6, 7, 8, 9]
    for seed in [0, 1, -1, 42, 10**30]:
        assert pick(xs, seed) == pick(xs, seed)


def test_pick_single_element() -> None:
    for seed in [0, 1, -7, 10**18]:
        assert pick([99], seed) == 99


def test_pick_negative_seed() -> None:
    xs = [1, 2, 3]
    assert pick(xs, -1) in xs
    assert pick(xs, -(10**20)) in xs


def test_pick_large_seed() -> None:
    xs = [1, 2, 3]
    assert pick(xs, 10**100) in xs


def test_pick_does_not_mutate() -> None:
    xs = [3, 1, 2]
    pick(xs, 17)
    assert xs == [3, 1, 2]


def test_pick_duplicates() -> None:
    assert pick([4, 4, 4], 123) == 4


def test_pick_covers_all_elements() -> None:
    xs = [10, 20, 30, 40]
    seen = {pick(xs, seed) for seed in range(200)}
    assert seen == set(xs)


def test_pick_empty_raises() -> None:
    with pytest.raises(ValueError):
        pick([], 0)

